AS x(course text,code text,video_id text,channel text);
CREATE TEMP TABLE _p ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset($fp1$[{"channel":"akita","title":"Como Computadores Funcionam?","id":"PLdsnXVqbHDUcQIuiH9b-i9A85H3A2ZW5W","units":["L/19411005","C/18121001","I/IFESCAR-ADM26-1-TECNOLOGIA-INFORMATICA"],"links":[{"course":"LESTI","code":"19411005"},{"course":"CTESP-STI","code":"18121001"},{"course":"IFES-CAR-ADM-INT-2026","code":"IFESCAR-ADM26-1-TECNOLOGIA-INFORMATICA"}],"url":"https://www.youtube.com/playlist?list=PLdsnXVqbHDUcQIuiH9b-i9A85H3A2ZW5W"},{"channel":"lhama","title":"Clean Architecture em Python (Remake)","id":"PLAgbpJQADBGK0opZ8ZuDX3zDjQck_QKMy","units":["L/19411016","L/19411006","C/18121006"],"links":[{"course":"LESTI","code":"19411016"},{"course":"LESTI","code":"19411006"},{"course":"CTESP-STI","code":"18121006"}],"url":"https://www.youtube.com/playlist?list=PLAgbpJQADBGK0opZ8ZuDX3zDjQck_QKMy"},{"channel":"aline","title":"Dicas rápidas: Excel","id":"PLLPRg8ARati5iIt6F6lgaRrqBogN6X_KD","units":["C/18121003","G/14181177","I/IFESCAR-ADM26-1-TECNOLOGIA-INFORMATICA"],"links":[{"course":"CTESP-STI","code":"18121003"},{"course":"LGEST","code":"14181177"},{"course":"IFES-CAR-ADM-INT-2026","code":"IFESCAR-ADM26-1-TECNOLOGIA-INFORMATICA"}],"url":"https://www.youtube.com/playlist?list=PLLPRg8ARati5iIt6F6lgaRrqBogN6X_KD"},{"channel":"aline","title":"Excel na Prática","id":"PLLPRg8ARati6JGVlsQq24b--fqz6CFzax","units":["C/18121003","C/18121007","G/14181177"],"links":[{"course":"CTESP-STI","code":"18121003"},{"course":"CTESP-STI","code":"18121007"},{"course":"LGEST","code":"14181177"}],"url":"https://www.youtube.com/playlist?list=PLLPRg8ARati6JGVlsQq24b--fqz6CFzax"}]$fp1$::jsonb)
AS x(channel text,title text,id text,url text,links jsonb);
CREATE TEMP TABLE _pl ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset($fpl1$[{"course":"LESTI","code":"19411005","playlist_id":"PLdsnXVqbHDUcQIuiH9b-i9A85H3A2ZW5W"},{"course":"CTESP-STI","code":"18121001","playlist_id":"PLdsnXVqbHDUcQIuiH9b-i9A85H3A2ZW5W"},{"course":"IFES-CAR-ADM-INT-2026","code":"IFESCAR-ADM26-1-TECNOLOGIA-INFORMATICA","playlist_id":"PLdsnXVqbHDUcQIuiH9b-i9A85H3A2ZW5W"},{"course":"LESTI","code":"19411016","playlist_id":"PLAgbpJQADBGK0opZ8ZuDX3zDjQck_QKMy"},{"course":"LESTI","code":"19411006","playlist_id":"PLAgbpJQADBGK0opZ8ZuDX3zDjQck_QKMy"},{"course":"CTESP-STI","code":"18121006","playlist_id":"PLAgbpJQADBGK0opZ8ZuDX3zDjQck_QKMy"},{"course":"CTESP-STI","code":"18121003","playlist_id":"PLLPRg8ARati5iIt6F6lgaRrqBogN6X_KD"},{"course":"LGEST","code":"14181177","playlist_id":"PLLPRg8ARati5iIt6F6lgaRrqBogN6X_KD"},{"course":"IFES-CAR-ADM-INT-2026","code":"IFESCAR-ADM26-1-TECNOLOGIA-INFORMATICA","playlist_id":"PLLPRg8ARati5iIt6F6lgaRrqBogN6X_KD"},{"course":"CTESP-STI","code":"18121003","playlist_id":"PLLPRg8ARati6JGVlsQq24b--fqz6CFzax"},{"course":"CTESP-STI","code":"18121007","playlist_id":"PLLPRg8ARati6JGVlsQq24b--fqz6CFzax"},{"course":"LGEST","code":"14181177","playlist_id":"PLLPRg8ARati6JGVlsQq24b--fqz6CFzax"}]$fpl1$::jsonb)
AS x(course text,code text,playlist_id text);
DO $pre$ BEGIN
 IF (SELECT count(*) FROM _c)<>8 OR (SELECT count(*) FROM _v)<>63
 OR (SELECT count(DISTINCT id) FROM _v)<>63
 OR (SELECT count(*) FROM _l)<>152 OR (SELECT count(*) FROM _p)<>4
 OR (SELECT count(*) FROM _pl)<>12
 THEN RAISE EXCEPTION 'Unexpected FACODI manifest counts';END IF;
 IF EXISTS(SELECT 1 FROM _v WHERE id !~ '^[A-Za-z0-9_-]{11}$' OR
 length(trim(title))<5 OR source NOT LIKE 'https://%')
 OR EXISTS(SELECT 1 FROM _p WHERE id !~ '^[A-Za-z0-9_-]{10,120}$' OR url NOT LIKE 'https://www.youtube.com/playlist?list=%')
 THEN RAISE EXCEPTION 'Invalid YouTube metadata';END IF;
 IF EXISTS(SELECT 1 FROM _l t LEFT JOIN facodi.courses c ON c.code=t.course AND c.published AND c.status='active'
 LEFT JOIN facodi.curricular_units u ON u.course_id=c.id AND u.code=t.code AND u.published AND u.status='active'
 WHERE u.id IS NULL)
 OR EXISTS(SELECT 1 FROM _pl t LEFT JOIN facodi.courses c ON c.code=t.course AND c.published AND c.status='active'
 LEFT JOIN facodi.curricular_units u ON u.course_id=c.id AND u.code=t.code AND u.published AND u.status='active'
 WHERE u.id IS NULL)
 THEN RAISE EXCEPTION 'Unpublished/missing academic course or UC'; END IF;
 IF EXISTS(SELECT 1 FROM _v v LEFT JOIN _c c ON c.key=v.channel WHERE c.key IS NULL)
 OR EXISTS(SELECT 1 FROM _p p LEFT JOIN _c c ON c.key=p.channel WHERE c.key IS NULL)
 THEN RAISE EXCEPTION 'Unknown source creator';END IF;
 IF EXISTS(SELECT 1 FROM _v v JOIN facodi.youtube_videos y ON y.youtube_video_id=v.id
 LEFT JOIN facodi.learning_objects lo ON lo.id=y.learning_object_id
 WHERE lo.id IS NULL OR NOT lo.published OR lo.status NOT IN('active','published'))
 THEN RAISE EXCEPTION 'Pre-existing unpublishable YouTube record; manual reconciliation required';END IF;
END $pre$;

INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,language,status,published,source_type,source_url,source_id,tags,metadata)
SELECT md5('facodi:eight:video:'||v.id)::uuid,'video',v.title,
 'facodi-oito-canais-video-'||v.id,
 'Vídeo externo de '||c.name||' selecionado pela FACODI por correspondência entre título e unidade curricular. O vídeo completo não foi visto nem homologado por docente. Consulte o original no YouTube.',
 'pt','active',true,'youtube',v.source,v.id,
 ARRAY['FACODI',c.name,c.topic,'recurso complementar'],
 jsonb_build_object('publisher',c.name,'youtube_handle',c.handle,'youtube_video_id',v.id,
 'source_verification',v.verification,'source_channel_index',c.source,'verified_on','2026-11-15',
 'curation_batch','facodi_eight_creator_channels_20261115','full_video_reviewed',false,
 'faculty_reviewed',false,'original_media_not_copied',true,'license_to_republish_not_verified',true)
FROM _v v JOIN _c c ON c.key=v.channel
WHERE NOT EXISTS(SELECT 1 FROM facodi.youtube_videos y WHERE y.youtube_video_id=v.id)
ON CONFLICT DO NOTHING;

INSERT INTO facodi.youtube_videos(id,learning_object_id,youtube_video_id,canonical_url,title,channel_title,language,metadata,status)
SELECT md5('facodi:eight:youtube:'||v.id)::uuid,md5('facodi:eight:video:'||v.id)::uuid,
v.id,v.source,v.title,c.name,'pt',
jsonb_build_object('channel_handle',c.handle,'verification_method',v.verification,'source_url',c.source,
'content_reviewed_in_full',false,'curation_batch','facodi_eight_creator_channels_20261115'),
'published'
FROM _v v JOIN _c c ON c.key=v.channel
WHERE NOT EXISTS(SELECT 1 FROM facodi.youtube_videos y WHERE y.youtube_video_id=v.id)
ON CONFLICT DO NOTHING;

-- Eight FACODI-owned thematic collections, never presented as playlists officially authored by the creators.
INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,language,status,published,source_type,source_url,source_id,tags,metadata)
SELECT md5('facodi:eight:collection:'||c.key)::uuid,'collection',
'FACODI · '||c.topic||' — '||c.name,'facodi-oito-canais-'||c.key,
'Coleção editorial independente da FACODI de vídeos do canal '||c.name||'. Não é uma playlist oficial do canal nem representa vínculo institucional.',
'pt','active',true,'external',c.source,'facodi-curated-channel-'||c.key,
ARRAY['FACODI','coleção temática',c.topic,c.name],
jsonb_build_object('source_channel',c.name,'source_handle',c.handle,'owner','FACODI',
'official_creator_playlist',false,'creator_endorsement',false,'curation_batch','facodi_eight_creator_channels_20261115')
FROM _c c ON CONFLICT DO NOTHING;

INSERT INTO facodi.learning_object_relations(id,parent_object_id,child_object_id,relation_type,position,created_by_mechanism,metadata)
SELECT md5('facodi:eight:collection-video:'||v.channel||':'||v.id)::uuid,
md5('facodi:eight:collection:'||v.channel)::uuid,y.learning_object_id,
'contains',v."order",'structured_catalog_import',
jsonb_build_object('review_status','approved','review_scope','title_and_channel_only',
'curation_batch','facodi_eight_creator_channels_20261115','faculty_reviewed',false,
'original_creator_channel',c.name,'full_video_reviewed',false,'verification_method',v.verification)
FROM _v v JOIN _c c ON c.key=v.channel
JOIN facodi.youtube_videos y ON y.youtube_video_id=v.id
JOIN facodi.learning_objects lo ON lo.id=y.learning_object_id AND lo.published AND lo.status IN('active','published')
ON CONFLICT DO NOTHING;

INSERT INTO facodi.learning_object_relations(id,parent_object_id,child_object_id,relation_type,position,created_by_mechanism,metadata)
SELECT md5('facodi:eight:uc-video:'||u.id::text||':'||v.id)::uuid,
u.learning_object_id,y.learning_object_id,'contains',
85000+row_number() over(partition by u.id order by v.channel,v."order")::integer,
'structured_catalog_import',
jsonb_build_object('review_status','approved','review_scope','title_and_channel_only',
'curation_batch','facodi_eight_creator_channels_20261115','original_creator',c.name,
'original_channel_handle',c.handle,'video_title_checked',true,'faculty_approved',false,
'full_video_reviewed',false,'course_code',course.code,'unit_code',u.code,
'mapping_basis','video_title_and_curriculum_topic','verification_method',v.verification)
FROM _l x JOIN _v v ON v.id=x.video_id
JOIN _c c ON c.key=v.channel
JOIN facodi.courses course ON course.code=x.course
JOIN facodi.curricular_units u ON u.course_id=course.id AND u.code=x.code
JOIN facodi.youtube_videos y ON y.youtube_video_id=v.id
JOIN facodi.learning_objects lo ON lo.id=y.learning_object_id AND lo.published AND lo.status IN('active','published')
ON CONFLICT DO NOTHING;

INSERT INTO facodi.learning_object_relations(id,parent_object_id,child_object_id,relation_type,position,created_by_mechanism,metadata)
SELECT md5('facodi:eight:course-collection:'||c.code||':'||x.channel)::uuid,
c.learning_object_id,md5('facodi:eight:collection:'||x.channel)::uuid,
'contains',94000+row_number() OVER(PARTITION BY c.id ORDER BY x.channel)::integer,
'structured_catalog_import',
jsonb_build_object('review_status','approved','review_scope','title_and_channel_only',
'curation_batch','facodi_eight_creator_channels_20261115','collection_owned_by','FACODI',
'external_creator_affiliation',false)
FROM(SELECT DISTINCT course,channel FROM _l) x
JOIN facodi.courses c ON c.code=x.course AND c.published
ON CONFLICT DO NOTHING;

-- Source playlists are verified URLs/titles; membership and creator ownership are not asserted.
INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,language,status,published,source_type,source_url,source_id,tags,metadata)
SELECT md5('facodi:eight:playlist:'||p.id)::uuid,'playlist',p.title,
'facodi-oito-canais-playlist-'||p.id,
'Referência externa do YouTube com URL e título confirmados. Não foram verificados todos os itens nem a titularidade da playlist. A FACODI não reproduz os vídeos nem afirma autoria da playlist.',
'pt','active',true,'youtube',p.url,p.id,
ARRAY['FACODI','playlist externa','curadoria',c.name],
jsonb_build_object('source_channel_context',c.name,'youtube_playlist_id',p.id,'playlist_title_checked',true,
'playlist_owner_verified',false,'playlist_membership_verified',false,
'items_automatically_imported',false,'curation_batch','facodi_eight_creator_channels_20261115')
FROM _p p JOIN _c c ON c.key=p.channel
ON CONFLICT DO NOTHING;

INSERT INTO facodi.learning_object_relations(id,parent_object_id,child_object_id,relation_type,position,created_by_mechanism,metadata)
SELECT md5('facodi:eight:uc-playlist:'||u.id::text||':'||p.id)::uuid,
u.learning_object_id,md5('facodi:eight:playlist:'||p.id)::uuid,
'contains',90000+row_number() OVER(PARTITION BY u.id ORDER BY p.id)::integer,
'structured_catalog_import',
jsonb_build_object('review_status','approved','review_scope','external_playlist_landing_page',
'curation_batch','facodi_eight_creator_channels_20261115',
'playlist_owner_verified',false,'members_verified',false)
FROM _pl x JOIN _p p ON p.id=x.playlist_id
JOIN facodi.courses c ON c.code=x.course
JOIN facodi.curricular_units u ON u.course_id=c.id AND u.code=x.code
ON CONFLICT DO NOTHING;

INSERT INTO facodi.external_sources(id,learning_object_id,source_type,external_id,source_url,title,metadata)
SELECT md5('facodi:eight:source:'||v.id)::uuid,
y.learning_object_id,'youtube',v.id,v.source,v.title,
jsonb_build_object('original_channel',c.name,'source_channel_handle',c.handle,
'verification_method',v.verification,'verified_on','2026-11-15',
'external_media_not_copied',true,'curation_batch','facodi_eight_creator_channels_20261115')
FROM _v v JOIN _c c ON c.key=v.channel
JOIN facodi.youtube_videos y ON y.youtube_video_id=v.id
ON CONFLICT DO NOTHING;

DO $post$ DECLARE n integer;links integer; BEGIN
 SELECT count(*) INTO n FROM _v v JOIN facodi.youtube_videos y ON y.youtube_video_id=v.id
 JOIN facodi.learning_objects o ON o.id=y.learning_object_id AND o.published;
 SELECT count(*) INTO links FROM _l x
 JOIN facodi.courses c ON c.code=x.course
 JOIN facodi.curricular_units u ON u.course_id=c.id AND u.code=x.code
 JOIN facodi.youtube_videos y ON y.youtube_video_id=x.video_id
 JOIN facodi.learning_object_relations r ON r.parent_object_id=u.learning_object_id
 AND r.child_object_id=y.learning_object_id AND r.relation_type='contains';
 IF n<>63 OR links<>152 OR
 (SELECT count(*) FROM facodi.learning_objects WHERE object_type='collection'
 AND metadata->>'curation_batch'='facodi_eight_creator_channels_20261115')<>8 OR
 (SELECT count(*) FROM facodi.learning_objects WHERE object_type='playlist'
 AND metadata->>'curation_batch'='facodi_eight_creator_channels_20261115')<>4
 THEN RAISE EXCEPTION 'Eight-channel source import not complete: videos %, relationships %',n,links; END IF;
END $post$;
